<?php
require_once __DIR__ . '/config.php'; require_once __DIR__ . '/local_ai_config.php'; header('Content-Type: application/json; charset=utf-8');
$action=$_POST['action']??'';$key=trim($_POST['session_key']??'');if(!$key)$key='web-'.bin2hex(random_bytes(8));
function get_session_id($key){global $conn;$s=$conn->prepare('SELECT id FROM chat_sessions WHERE session_key=? ORDER BY id DESC LIMIT 1');$s->bind_param('s',$key);$s->execute();$r=$s->get_result()->fetch_assoc();if($r)return(int)$r['id'];$uid=$_SESSION['user']['id']??null;$q=$conn->prepare('INSERT INTO chat_sessions(session_key,user_id) VALUES(?,?)');$q->bind_param('si',$key,$uid);$q->execute();return$q->insert_id;}
function docs_for($text){global$conn;$t=mb_strtolower($text);$show=str_contains($t,'document')||str_contains($t,'pdf')||str_contains($t,'form')||str_contains($t,'download')||str_contains($t,'application')||str_contains($t,'license')||str_contains($t,'licence')||str_contains($t,'medical')||str_contains($t,'report')||str_contains($t,'fitness')||str_contains($t,'permit')||str_contains($t,'ලේඛ')||str_contains($t,'පෝරම')||str_contains($t,'බාගත')||str_contains($t,'අයදුම්')||str_contains($t,'බලපත්‍ර')||str_contains($t,'වෛද්‍ය')||str_contains($t,'වාර්තා');if(!$show)return[];$docs=[];$result=$conn->query('SELECT title_en,title_si,file_path FROM documents WHERE active=1 ORDER BY id');while($doc=$result->fetch_assoc()){if(!is_file(__DIR__.'/'.$doc['file_path']))continue;$docs[]=['title'=>$doc['title_en'].' / '.$doc['title_si'],'url'=>BASE_URL.'/'.str_replace('%2F','/',rawurlencode($doc['file_path']))];}return$docs;}
function find_knowledge($question){global$conn;$words=preg_split('/[^\p{L}\p{N}]+/u',mb_strtolower($question));$stop=['what','where','when','how','can','could','please','tell','about','the','and','for','from','with','is','are','you','මට','මොකක්','මොනවද','කොහොමද','කොහේද','කවද්ද','ගැන','දෙන්න','ඕන','එක','ද','කියන්න','පුළුවන්ද'];$words=array_values(array_unique(array_filter($words,function($w)use($stop){return mb_strlen($w)>=2&&!in_array($w,$stop,true);})));$words=array_slice($words,0,10);if(!$words)return[];$parts=[];$types='';$vals=[];foreach($words as$w){$parts[]='(question LIKE ? OR answer LIKE ?)';$types.='ss';$like='%'.$w.'%';$vals[]=$like;$vals[]=$like;}$sql='SELECT question,answer,language FROM faqs WHERE active=1 AND ('.implode(' OR ',$parts).') LIMIT 15';$st=$conn->prepare($sql);if(!$st)return[];$st->bind_param($types,...$vals);$st->execute();$res=$st->get_result();$out=[];while($row=$res->fetch_assoc())$out[]=$row;return$out;}
function call_local_ai($question,$history,$knowledge){$kb='';foreach($knowledge as$i=>$k){$kb.="\n[".($i+1)."] Q: ".strip_tags($k['question'])."\nA: ".strip_tags($k['answer'])."\n";}if($kb==='')$kb='\n[No matching FAQ found.]\n';$prompt="You are the local virtual assistant for the Southern Provincial Road Passenger Transport Authority (RPTA), Sri Lanka.\n\nSTRICT LANGUAGE RULES:\n- Sinhala question => answer ONLY in natural Sinhala Unicode.\n- English question => answer ONLY in clear English.\n- Mixed question => clear bilingual answer is allowed.\n- NEVER output Chinese, Japanese, Korean or random characters.\n- Never invent official rules, fees, phone numbers, routes or procedures.\n- Use the RPTA knowledge below as the trusted source.\n- If insufficient information, say the information is not available in the current knowledge base and advise contact number ".CONTACT_PHONE.".\n- Keep answers concise.\n\nRPTA KNOWLEDGE:\n$kb\n\nRECENT CHAT:\n";foreach(array_slice($history,-6)as$h)$prompt.=($h['sender']==='bot'?'Assistant: ':'Passenger: ').strip_tags($h['message'])."\n";$prompt.="\nPASSENGER QUESTION:\n$question\n\nANSWER:";$payload=['model'=>LOCAL_AI_MODEL,'prompt'=>$prompt,'stream'=>false,'options'=>['temperature'=>0.15,'top_p'=>0.8,'num_predict'=>280]];$ch=curl_init(LOCAL_AI_URL);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>180,CURLOPT_PROXY=>'',CURLOPT_NOPROXY=>'127.0.0.1,localhost']);$raw=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false||$err)return['error'=>'Local AI connection error: '.$err];$data=json_decode($raw,true);if($http>=400)return['error'=>$data['error']??('Ollama error HTTP '.$http)];$text=trim($data['response']??'');if($text==='')return['error'=>'The local AI returned an empty response.'];return['answer'=>nl2br(h($text))];}
if($action==='ask'){$q=trim($_POST['question']??'');if($q===''){echo json_encode(['error'=>'Please enter a question.'],JSON_UNESCAPED_UNICODE);exit;}$sid=get_session_id($key);$s=$conn->prepare("INSERT INTO chat_messages(chat_session_id,sender,message) VALUES(?, 'user', ?)");$s->bind_param('is',$sid,$q);$s->execute();$hist=[];$hs=$conn->prepare('SELECT sender,message FROM chat_messages WHERE chat_session_id=? ORDER BY id DESC LIMIT 10');$hs->bind_param('i',$sid);$hs->execute();$rr=$hs->get_result();while($x=$rr->fetch_assoc())$hist[]=$x;$hist=array_reverse($hist);$knowledge=find_knowledge($q);
 // Strong FAQ match: return database answer directly. This makes suggested/known questions stable and accurate.
 $direct=null;$ql=mb_strtolower(trim($q));foreach($knowledge as$k){$kl=mb_strtolower(trim($k['question']));similar_text($ql,$kl,$pct);if($pct>=72){$direct=$k;break;}}
 if($direct){$answer=nl2br(h($direct['answer']));$mode='Knowledge Base';}else{$result=call_local_ai($q,$hist,$knowledge);if(!empty($result['error'])){echo json_encode(['error'=>$result['error'],'local_ai'=>true,'model'=>LOCAL_AI_MODEL,'documents'=>docs_for($q)],JSON_UNESCAPED_UNICODE);exit;}$answer=$result['answer'];$mode='Local Generative AI';}
 $ans='🤖 <b>RPTA Assistant — '.$mode.':</b><br>'.$answer;$s2=$conn->prepare("INSERT INTO chat_messages(chat_session_id,sender,message) VALUES(?, 'bot', ?)");$s2->bind_param('is',$sid,$ans);$s2->execute();echo json_encode(['answer'=>$ans,'documents'=>docs_for($q),'local_ai'=>true,'model'=>LOCAL_AI_MODEL,'knowledge_items'=>count($knowledge),'answer_mode'=>$mode],JSON_UNESCAPED_UNICODE);exit;}
if($action==='feedback'){$sid=get_session_id($key);$rating=max(1,min(5,(int)($_POST['rating']??5)));$note=trim($_POST['note']??'');$uid=$_SESSION['user']['id']??null;$s=$conn->prepare('INSERT INTO feedback(chat_session_id,user_id,rating,note) VALUES(?,?,?,?)');$s->bind_param('iiis',$sid,$uid,$rating,$note);$s->execute();$conn->query('UPDATE chat_sessions SET ended_at=NOW() WHERE id='.(int)$sid);echo json_encode(['ok'=>true],JSON_UNESCAPED_UNICODE);exit;}
echo json_encode(['error'=>'Invalid request'],JSON_UNESCAPED_UNICODE);
